<template><a-card class="panel-card"><a-table :loading="loading" :data-source="records" :columns="columns" row-key="id" :scroll="{x:900}"><template #bodyCell="{column,record}"><template v-if="column.key==='path'"><strong>{{record.remote_path}}</strong><div class="muted">{{record.local_path}}</div></template><template v-if="column.key==='status'"><a-tag :color="colors[record.status]">{{statuses[record.status]||'未知'}}</a-tag></template><template v-if="column.key==='count'">STRM {{record.new_strm||0}} / 元数据 {{record.new_meta||0}} / 上传 {{record.new_upload||0}}</template><template v-if="column.key==='time'">{{formatTime(record.finish_at)}}</template></template></a-table></a-card></template><script setup lang="ts">import{onMounted,ref}from'vue';import{get}from'../../services/http';import{formatTime}from'../../core/format';import type{AnyMap,SyncRecord}from'../../types';const loading=ref(true),records=ref<SyncRecord[]>([]),statuses=['等待中','进行中','已完成','失败'],colors=['default','processing','success','error'];const columns=[{title:'ID',dataIndex:'id'},{title:'路径',key:'path'},{title:'类型',dataIndex:'is_full_sync',customRender:({text}:{text:boolean})=>text?'全量':'增量'},{title:'状态',key:'status'},{title:'新增内容',key:'count'},{title:'完成时间',key:'time'},{title:'失败原因',dataIndex:'fail_reason'}];onMounted(async()=>{try{const d=await get<AnyMap>('/sync/records?page=1&page_size=100');records.value=d.records||[]}finally{loading.value=false}})</script>
